#!/usr/bin/env bash
# GENERATED BY GALAXY - safe to customize, Galaxy will not overwrite it.
#
# 1. Design system -> packages/design_system/lib
# 2. Pages -> <app>/lib/src/modules
# 3. Routes -> <app>/lib/src/app/routes
# 4. Assets -> <app>/assets
# 5. Asset constants -> <app>/lib/src/utils/constants/assets_path.dart
#
# Usage:
# bash scripts/generate_design.sh [tokens.json] [dsOut] [modulesOut] [assetManifest] [routesOut]
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

TOKENS="${1:-token_pipeline/tokens.json}"
DS_OUT="${2:-packages/design_system/lib}"
PAGES_OUT="${3:-apps/demo_app/lib/src/modules}"
ASSET_MANIFEST="${4:-apps/demo_app/assets/galaxy_assets.json}"
ROUTES_OUT="${5:-apps/demo_app/lib/src/app/routes}"
APP_DIR="$ROOT/apps/demo_app"
CONFIG_FILE="$ROOT/token_pipeline/galaxy.config.json"

ensure_android_kotlin_plugin() {
  local gradle_file="$APP_DIR/android/app/build.gradle.kts"
  if [ ! -f "$gradle_file" ]; then return; fi
  python3 - "$gradle_file" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
source = path.read_text()
if 'id("org.jetbrains.kotlin.android")' in source or 'id("kotlin-android")' in source:
    raise SystemExit(0)
android_plugin = 'id("com.android.application")'
if android_plugin not in source:
    raise SystemExit(f"Android application plugin not found in {path}")
path.write_text(source.replace(android_plugin, android_plugin + '\n    id("org.jetbrains.kotlin.android")', 1))
PY
}

if [ ! -f "$ROOT/$TOKENS" ]; then
  echo "Token file not found: $TOKENS" >&2
  exit 66
fi

echo "============================================"
echo "Galaxy Design Codegen"
echo "Tokens: $ROOT/$TOKENS"
echo "Design system: $ROOT/$DS_OUT"
echo "Pages: $ROOT/$PAGES_OUT"
echo "Asset manifest: $ROOT/$ASSET_MANIFEST"
echo "Routes: $ROOT/$ROUTES_OUT"
echo "============================================"

if [ -f "$CONFIG_FILE" ]; then
  if ! command -v jq >/dev/null 2>&1; then
    echo "jq is required to read selected Flutter platforms from galaxy.config.json." >&2
    exit 127
  fi
  TECHNOLOGY="$(jq -r '.technology.technology // "flutter"' "$CONFIG_FILE")"
  if [ "$TECHNOLOGY" = "flutter" ]; then
    if [ ! -f "$APP_DIR/pubspec.yaml" ]; then
      echo "Flutter app pubspec.yaml not found: $APP_DIR/pubspec.yaml" >&2
      exit 66
    fi
    PLATFORMS="$(jq -r '(.technology.platforms // ["android", "ios"]) | map(select(. == "android" or . == "ios" or . == "web" or . == "macos" or . == "linux" or . == "windows")) | unique | join(",")' "$CONFIG_FILE")"
    if [ -z "$PLATFORMS" ]; then
      echo "No valid Flutter platforms are selected in token_pipeline/galaxy.config.json." >&2
      exit 65
    fi
    if ! command -v flutter >/dev/null 2>&1; then
      echo "Flutter is required to create selected platform folders." >&2
      exit 127
    fi
    echo "Creating Flutter platform folders: $PLATFORMS"
    (cd "$APP_DIR" && flutter create --no-pub --platforms="$PLATFORMS" .)
    case ",$PLATFORMS," in
      *,android,*) ensure_android_kotlin_plugin ;;
    esac
  fi
fi

if [ -f "$ROOT/$ASSET_MANIFEST" ]; then
  echo "Asset manifest found."
else
  echo "Asset manifest not found. Asset constants will not be generated."
fi

cd "$ROOT/tools/design_codegen_runner"

echo "Running dart pub get..."
dart pub get

echo "Running design_codegen..."

dart run design_codegen:generate_design_system \
  "$ROOT/$TOKENS" \
  "$ROOT/$DS_OUT" \
  "$ROOT/$PAGES_OUT" \
  "$ROOT/$ASSET_MANIFEST" \
  "$ROOT/$ROUTES_OUT"

echo "============================================"
echo "Galaxy Design Codegen completed successfully."
echo "============================================"
